-- Vault · Wisdom: the practice loop on every lesson, and thirteen new pieces
-- from the thinkers the course did not yet carry.
--
-- Original educational text on documented ideas. No quotations are attributed
-- to any thinker; every piece names its source works in references_json and a
-- "Note" row states the relationship. The evidence chip rates the PRACTICE
-- (what the reader does in try_today), never the philosophy behind it.
-- Mirrored for the coach in supabase/functions/_shared/wisdom-catalog.ts and
-- for the client map in src/data/vault-masters.ts / vault-paths.ts. Update all
-- together.

-- ── 1. The eleven course lessons get a master, a question in, a question out ──
UPDATE public.vault_articles SET master_slug = NULL, practice_minutes = 10,
  reflect_prompt = 'Which teacher on this list have you swallowed whole, practice and metaphysics together? What did you keep, and what did you quietly drop?',
  integrate_prompt = 'You wrote three sentences for one source. Which of the three was hardest to finish, and what does that say about how you read?'
WHERE slug = 'how-to-read-a-teacher';

UPDATE public.vault_articles SET master_slug = 'clear', practice_minutes = 10,
  reflect_prompt = 'Finish the sentence honestly, not aspirationally: right now my actions say I am the kind of person who …',
  integrate_prompt = 'You put one identity sentence where you would see it at check-in time. Did it change what you did, or only how you felt about what you did?'
WHERE slug = 'atomic-habits-identity';

UPDATE public.vault_articles SET master_slug = 'tolle', practice_minutes = 5,
  reflect_prompt = 'Which thought loop ran most often this week, and how many times did it actually change anything?',
  integrate_prompt = 'After three sixty-second returns: how long did the gap last before the thinker started again, and what pulled you back?'
WHERE slug = 'power-of-now-presence';

UPDATE public.vault_articles SET master_slug = 'tolle', practice_minutes = 5,
  reflect_prompt = 'Name one role, opinion or number you would feel smaller without. What does defending it cost you?',
  integrate_prompt = 'You caught one identification in the act. What did the defence feel like in the body, and what happened when you did not act on it?'
WHERE slug = 'new-earth-ego';

UPDATE public.vault_articles SET master_slug = 'byrne', practice_minutes = 5,
  reflect_prompt = 'Which feeling do you fight hardest when it shows up at check-in time?',
  integrate_prompt = 'You welcomed one difficult feeling instead of fighting it. Did it grow, shrink or change shape, and how long did it stay?'
WHERE slug = 'greatest-secret-awareness';

UPDATE public.vault_articles SET master_slug = 'sharma', practice_minutes = 15,
  reflect_prompt = 'Score your last month on the eight forms, one to five each. Which score would surprise someone who only sees your streak?',
  integrate_prompt = 'You moved one hour toward the poorest form. Was the resistance in the calendar, or in you?'
WHERE slug = 'eight-forms-of-wealth';

UPDATE public.vault_articles SET master_slug = 'jung', practice_minutes = 10,
  reflect_prompt = 'Who irritated you out of all proportion this week, and which quality in them did it?',
  integrate_prompt = 'You traced one irritation back to a quality you disown in yourself. Where has that quality shown up in you since, and what did you do with it?'
WHERE slug = 'jung-shadow-individuation';

UPDATE public.vault_articles SET master_slug = 'dispenza', practice_minutes = 10,
  reflect_prompt = 'Which upcoming moment do you already rehearse badly in your head, obstacle and all?',
  integrate_prompt = 'You rehearsed one scene with the feeling included. When the real moment came, what was familiar and what was not?'
WHERE slug = 'dispenza-rehearsal';

UPDATE public.vault_articles SET master_slug = 'huberman', practice_minutes = 10,
  reflect_prompt = 'Of light, breath, dopamine and cold, which one is missing from your mornings, and what fills its place?',
  integrate_prompt = 'You ran one protocol for three days. What changed in the check-in numbers, and what changed that no number tracks?'
WHERE slug = 'huberman-protocol-stack';

UPDATE public.vault_articles SET master_slug = 'watts', practice_minutes = 10,
  reflect_prompt = 'What are you gripping right now, a result, a streak, a person, that the gripping itself is spoiling?',
  integrate_prompt = 'You did one thing purely for its own sake, unlogged. How did it feel not to count it, and what did you want to count anyway?'
WHERE slug = 'watts-wisdom-of-insecurity';

UPDATE public.vault_articles SET master_slug = NULL, practice_minutes = 20,
  reflect_prompt = 'Which of the nine practices would you keep if you could keep only one, and why that one?',
  integrate_prompt = 'You ran the stack for a week. Which practice earned its minutes, and which one did you let go of without missing it?'
WHERE slug = 'wisdom-practice-stack';

-- ── 2. Thirteen new pieces ──────────────────────────────────────────────────
INSERT INTO public.vault_articles
  (category_id, slug, title, subtitle, summary, evidence_tier, read_time_min,
   benefits, risks, body_md, why_it_matters, key_takeaways, try_today,
   references_json, quiz, display_order, lesson_number, course_role,
   master_slug, reflect_prompt, integrate_prompt, practice_minutes)
VALUES

-- ─── Frankl ───
('wisdom', 'frankl-meaning-responsibility',
 'Frankl: Meaning Is Made, Not Found',
 'Viktor Frankl''s reversal: stop asking what you want from life and answer what life is asking of you',
 'Frankl, a psychiatrist who survived four camps, built a therapy on one observation: people who had something to answer for held on. His method turns the question around. Meaning is not a feeling you wait for; it is a task you take on.',
 'promising', 5,
 ARRAY['A concrete way to locate meaning in an ordinary week: through work, through people, through how you carry what cannot be changed','A reframe for suffering that does not pretend it is good, only that your response to it is still yours','The link between purpose and follow-through that the habit literature keeps finding'],
 ARRAY['Meaning research shows strong associations with wellbeing and health behaviour; it cannot prove that adopting a purpose causes the benefits','Frankl''s claims come from clinical observation and his own survival, not controlled trials; the practice earns its chip, the biography does not','A meaning that is only ever future-facing can become another way of not living now'],
 E'Viktor Frankl was a Viennese psychiatrist before the war and a prisoner in Auschwitz and Dachau during it. Man''s Search for Meaning, written in nine days in 1946, is half memoir and half the outline of the therapy he called logotherapy. Its claim is narrow and testable in your own week: the people who kept going had something to answer for. A manuscript to finish. A person waiting. A way of carrying a situation nobody could change.\n\n**The question, reversed**\nMost of us ask what we want from life and then feel let down by the answer. Frankl turns it around. Life is asking questions of you, in the concrete form of this week''s situations, and you answer with what you do. Meaning is not found lying around like a coin; it is made by responding. That is why he called responsibility the other half of freedom. You are free to choose your response; you are responsible for the one you choose.\n\n**Three roads to it**\nFrankl named three ways meaning shows up. Through what you create or do: your craft, your training, the work only you will finish. Through what you encounter: people, beauty, love, the things that ask you to pay attention. And through the attitude you take toward suffering you cannot remove: illness, loss, an injury that ended a season. The third road is the one that made his method famous, and it is also the one most often misused. He never said suffering is good. He said that when it is unavoidable, the stance you take toward it is still yours, and that stance can carry meaning.\n\n**What the research adds**\nSince Steger''s 2006 meaning-in-life work, presence of meaning has been measured in tens of thousands of people. It tracks with lower depression, better sleep, more physical activity and, in large cohorts, lower mortality. Those are associations. They do not show that writing a purpose statement makes you healthier. What they do show is that the thing Frankl pointed at is real, common and measurable, and that people who have it behave differently on ordinary days. That is why the chip says promising: the practice below has a plausible mechanism and early support, and no trial has run it as written.\n\n**Where it meets your week**\nThe streak and the check-in are answers to a question you set for yourself. They hold up on days when the question is alive and fall apart when it goes quiet. Frankl''s move is to keep the question audible: not "do I feel like it" but "what is this day asking of me, and who is on the other end of the answer".',
 'A streak survives on the days you remember what it is for. Frankl gives you a way to keep that answer in reach, and a way to stand toward the parts of a week you cannot change.',
 ARRAY['Meaning is a response, not a discovery: life asks, you answer with action.','Three roads: what you make, whom you meet, how you carry what cannot be changed.','The evidence supports the pattern, not the biography; run the practice and judge it by your week.'],
 ARRAY['Write down three questions this month is asking of you, in concrete terms: a person, a task, a situation to carry.','Choose one and write the answer as an action you will take within seven days, with a day attached.','Do it, and note afterwards whether the meaning arrived before, during or after the action.'],
 '[{"author": "Note", "title": "Original lesson on the ideas of Viktor Frankl; not affiliated with the author''s estate or publishers"}, {"author": "Frankl, V. E.", "title": "Man''s Search for Meaning", "year": 1946}, {"author": "Steger, M. F. et al.", "title": "The Meaning in Life Questionnaire: Assessing the presence of and search for meaning in life (J. Couns. Psychol.)", "year": 2006}, {"author": "Cohen, R. et al.", "title": "Purpose in life and its relationship to all-cause mortality and cardiovascular events: a meta-analysis (Psychosom. Med.)", "year": 2016}]'::jsonb,
 '[{"q": "What does Frankl mean by reversing the question?", "choices": ["Stop wanting things", "Ask what life is asking of you and answer with action", "Find your purpose by thinking harder"], "correct": 1, "explain": "Meaning is made by responding to the concrete situations in front of you, not found by introspection alone."}, {"q": "What does the meaning-in-life research actually show?", "choices": ["Purpose statements cause better health", "Presence of meaning is associated with better wellbeing and behaviour", "Nothing measurable"], "correct": 1, "explain": "Strong associations in large samples, not proof of cause. The practice earns a promising chip, not a strong one."}]'::jsonb,
 320, NULL, 'protocol',
 'frankl',
 'Which difficulty in your life have you been asking "why me" about? What would it look like to ask what it is asking of you instead?',
 'You answered one of life''s questions with an action. Did the meaning arrive before the action, during it, or only afterwards?',
 10),

-- ─── Epictetus ───
('wisdom', 'epictetus-dichotomy-of-control',
 'Epictetus: The Line Between Up to You and Not',
 'A former slave''s first lesson: sort everything into what is yours to move and what never was',
 'The Enchiridion opens with a sorting rule. Some things are up to us: our judgements, our aims, what we go after and what we avoid. Others are not: the body, reputation, other people, outcomes. Most distress comes from treating the second group as the first. The practice is the sort, done daily, in writing.',
 'promising', 4,
 ARRAY['A five-minute morning practice that turns vague worry into one action and one release','The frame behind cognitive therapy: it is the judgement about the event, not the event, that you can work on','A way to compete hard for outcomes you do not control without being owned by them'],
 ARRAY['The sort can be misread as passivity; the Stoics trained for outcomes as hard as anyone, they just refused to stake their peace on them','Cognitive reappraisal has solid trial evidence; the Stoic version as written has plausible mechanism and mostly indirect support, hence promising','Some things are partly up to you; the sort is a first cut, not a law'],
 E'Epictetus was born a slave in what is now Turkey, was freed, taught philosophy in Rome until the emperor expelled the philosophers, and then taught in Greece until he died around 135 AD. He wrote nothing down. His student Arrian recorded the lectures as the Discourses and condensed them into a pocket manual, the Enchiridion. Its first paragraph is the whole method.\n\n**The sort**\nSome things are up to us and some are not. Up to us: our opinions, our impulses, what we desire and what we avoid, everything that is our own doing. Not up to us: the body, property, reputation, position, everything that is not our own doing. Epictetus then makes the claim that gives Stoicism its edge. If you treat what is not up to you as if it were, you will be blocked, frustrated and at the mercy of other people. If you keep the line straight, nobody can compel you and nothing can harm the part of you that matters.\n\n**What it is not**\nThe sort is often read as a licence to stop caring. The Stoics did not read it that way. They ran for office, led armies, wrote to their students about training the body. The distinction they drew was between the target and the aim. You aim at the outcome with everything you have. You stake your peace only on the aim, because the outcome was never fully yours. Later Stoics called this the reserve clause: I will do this, if nothing prevents it. It is the mental posture of someone who trains hard for a race they may not win.\n\n**Where it meets the science**\nThe line from the Enchiridion runs straight into modern cognitive therapy. Albert Ellis and Aaron Beck both credited Epictetus for the observation that it is our judgements about events, not events themselves, that disturb us, and cognitive reappraisal is now one of the best-supported techniques in psychology. The daily sort as a written practice has not been tested on its own in a trial; that is why the chip says promising rather than strong. The mechanism is the reappraisal literature''s; the ritual is the Stoics''.\n\n**Where it meets your week**\nA rank on a board, a session that goes badly, someone''s reaction to your post: none of it is in the first column. The training you do, how you read the number, whether you show up tomorrow: all of it is. The practice below takes five minutes and leaves you with one action and one thing set down.',
 'Boards, battles and streaks put numbers in front of you every day that you do not fully control. The sort is how you compete for them without letting them run your nervous system.',
 ARRAY['Up to you: judgements, aims, effort. Not up to you: outcomes, bodies, other people.','Aim at outcomes with everything; stake your peace only on what is yours.','The frame is the ancestor of cognitive reappraisal, which has strong evidence; the written daily sort is promising.'],
 ARRAY['Write down the three things weighing on you this morning.','Draw a line: for each, name the part that is up to you and the part that is not.','For the up-to-you column, one action today. For the other column, one sentence of release, said once, out loud.'],
 '[{"author": "Note", "title": "Original lesson on the ideas of Epictetus as recorded by Arrian; the Enchiridion and Discourses are in the public domain"}, {"author": "Epictetus (Arrian, ed.)", "title": "Enchiridion", "year": 125}, {"author": "Robertson, D.", "title": "How to Think Like a Roman Emperor: The Stoic Philosophy of Marcus Aurelius", "year": 2019}, {"author": "Webb, T. L. et al.", "title": "Dealing with feeling: A meta-analysis of the effectiveness of strategies derived from the process model of emotion regulation (Psychol. Bull.)", "year": 2012}]'::jsonb,
 '[{"q": "Which of these is in the up-to-you column?", "choices": ["Your rank on the board", "How you judge your rank on the board", "What other people think of your rank"], "correct": 1, "explain": "Judgements, aims and effort are yours. The number and other people''s reactions are not."}, {"q": "What did the Stoics do about outcomes they could not control?", "choices": ["Stopped trying for them", "Aimed at them fully but staked their peace on the aim, not the result", "Pretended they did not want them"], "correct": 1, "explain": "The reserve clause: full effort, held loosely."}]'::jsonb,
 321, NULL, 'protocol',
 'epictetus',
 'What did you try to control this week that was never up to you, and what did the trying cost?',
 'You sorted three worries. How much of your day''s tension sat in the column that was never yours?',
 5),

-- ─── Marcus Aurelius ───
('wisdom', 'marcus-aurelius-morning-practice',
 'Marcus Aurelius: Notes to Himself',
 'The most powerful man alive kept a private notebook to prepare for difficult people and to zoom out',
 'The Meditations were never meant to be read. They are an emperor''s reminders to himself, written in camp during a plague and a war, and they show a practice: expect the day''s difficulty before it arrives, name what is yours in it, and look at it from far enough away that it shrinks. The practice is a three-line morning note.',
 'promising', 4,
 ARRAY['A morning ritual that puts a gap between a difficult person and your first reaction','The view from above: a reliable way to shrink a problem to its real size','A private page that has some of the evidence base of expressive writing behind it'],
 ARRAY['Expressive writing has trial support; the specific Stoic three-line note has not been tested on its own, so the chip says promising','Preparing for difficulty can tip into rehearsing dread; keep the note short and end it with the zoom-out','Marcus wrote as a Stoic with a cosmology most readers do not share; the practice works without it'],
 E'Marcus Aurelius ruled Rome from 161 to 180 AD, through the Antonine plague and years of war on the Danube. In camp, at night, he wrote in Greek to himself. He called the notebook "to himself"; we call it the Meditations. Nothing in it is addressed to a reader. That is what makes it useful: it is a working document from someone under pressure, and the practices repeat because he needed them repeated.\n\n**Expect the difficult ones**\nThe most-quoted passage in the book, at the start of Book 2, is a morning drill. Tell yourself before the day starts that you will meet people who are meddling, ungrateful, arrogant, dishonest. Then remind yourself why: they do not know better, and they are, like you, part of the same whole, so you cannot be harmed by them and cannot rightly be angry with them. Whatever you make of the metaphysics, the mechanics are sharp. Naming the difficulty before it arrives means it lands on a prepared mind. The gap between the event and your reaction, the thing Epictetus'' sort creates, is put in place in advance.\n\n**The view from above**\nThe second recurring move is scale. Marcus repeatedly imagines looking down on cities and armies from a height, or forward across centuries, until the thing that seemed enormous is a small event among countless others. Pierre Hadot called this the view from above and traced it through the whole Stoic tradition. It is not detachment. It is a change of frame that lets you act without the distortion of a problem that has filled the whole windscreen.\n\n**What the research adds**\nWriting privately about difficult experiences has been studied since Pennebaker''s 1986 experiments: modest but repeated benefits for mood, health visits and immune markers across dozens of trials. The morning note below borrows that mechanism and adds two Stoic moves, the preparation and the zoom-out. As a package it has not been trialled, which is why the chip is promising rather than strong.\n\n**Where it meets your week**\nSquads, boards and a comment thread put other people in front of you before breakfast. A three-line note takes under five minutes, and it is written before you have looked at any of them.',
 'Other people are the part of your day you control least and react to most. Marcus wrote his way into a prepared mind every morning; the same three lines fit before your first check-in.',
 ARRAY['Name the day''s likely difficulty before it arrives, and it lands on a prepared mind.','The view from above shrinks a problem to its real size without pretending it is not there.','Private writing about difficulty has trial support; the Stoic note is that mechanism with two extra moves.'],
 ARRAY['Before you open anything else, write one line: the person or situation most likely to test you today.','Write one line naming what in that situation is yours: your tone, your effort, your reading of it.','Write one line from above: this day, this week, seen from a year away. Then close the notebook and start.'],
 '[{"author": "Note", "title": "Original lesson on the ideas of Marcus Aurelius; the Meditations are in the public domain"}, {"author": "Marcus Aurelius", "title": "Meditations (Ta eis heauton)", "year": 180}, {"author": "Hadot, P.", "title": "The Inner Citadel: The Meditations of Marcus Aurelius", "year": 1998}, {"author": "Pennebaker, J. W. & Beall, S. K.", "title": "Confronting a traumatic event: Toward an understanding of inhibition and disease (J. Abnorm. Psychol.)", "year": 1986}]'::jsonb,
 '[{"q": "Why does Marcus name difficult people before the day begins?", "choices": ["To avoid them", "So the difficulty lands on a prepared mind with a gap before the reaction", "To feel superior to them"], "correct": 1, "explain": "The preparation puts the gap between event and reaction in place in advance."}, {"q": "What is the view from above for?", "choices": ["Detaching from life", "Seeing a problem at its real size so you can act without distortion", "Feeling insignificant"], "correct": 1, "explain": "A change of frame, not a retreat from action."}]'::jsonb,
 322, NULL, 'protocol',
 'marcus-aurelius',
 'Which person or situation is most likely to test you today, and what is your usual first reaction to it?',
 'You wrote the morning note before the day. When the difficulty came, was there a gap between it and your reaction that was not there before?',
 5),

-- ─── Seneca ───
('wisdom', 'seneca-on-time',
 'Seneca: You Are Not Short of Time, You Are Wasting It',
 'A rich, busy, compromised man on the one resource nobody gets back, and the audit that shows where yours goes',
 'Seneca''s short essay on the shortness of life makes one argument: life is long enough if you use it, and most people hand their hours to other people''s demands, to distraction and to a future that never arrives. The practice is an honest audit of the last seven days and one hour reclaimed.',
 'promising', 4,
 ARRAY['A clear look at where a week actually went, which is almost never where you think','One reclaimed hour a week, chosen on purpose, which compounds faster than any productivity method','The evening review: a Stoic habit that turns the day into feedback instead of a blur'],
 ARRAY['Time-use awareness helps people change how they spend time; the effect sizes are modest and the audit below has not been trialled as written','Seneca was wealthy and politically compromised; read him for the argument, not as a model of a simple life','An audit can become a second job; do it once a week, not daily'],
 E'Lucius Annaeus Seneca was a playwright, a senator, tutor and then adviser to Nero, one of the richest men in Rome, and a Stoic who was ordered to kill himself in 65 AD and did. He is the most human of the Stoics because he failed at his own advice often and wrote about it anyway. His essay On the Shortness of Life is addressed to a friend, Paulinus, who ran Rome''s grain supply, and it is short enough to read in an hour.\n\n**The argument**\nWe complain that life is short. Seneca says it is not; it is long enough, and we waste most of it. Wasted how? On other people''s claims on us, on business that is not ours, on drink and sleep past need, on worry about the future and regret about the past, and above all on postponement: the plan to really start living once some condition is met. People guard their money and their land fiercely, he notes, and hand out their hours to anyone who asks.\n\n**The evening review**\nElsewhere, in the essay On Anger, Seneca describes a nightly habit he learned from his teacher Sextius: when the lamp is out and the house is quiet, go back over the day and ask what you did badly, what you did well, what you left undone. He says he sleeps better for it. It is the ancestor of every evening reflection, including the one in this app.\n\n**What the research adds**\nThe modern version of Seneca''s audit is time-use research. When people record how they actually spend a week, the record and the story they told themselves diverge, and the divergence is where the change comes from: seeing hours go to low-value defaults tends to move them. The effects in trials are modest, and the specific one-week audit plus one reclaimed hour has not been tested on its own. The mechanism is plausible and the cost is fifteen minutes, so the chip says promising.\n\n**Where it meets your week**\nThe check-in already asks how you slept and whether you trained. It does not ask where the other fourteen hours went. Once a week, this practice does, and it ends with one hour moved on purpose rather than a vague resolve to do better.',
 'Consistency is a time problem before it is a motivation problem. Seneca''s audit shows where the hours actually go, and moving one of them on purpose is the smallest change that compounds.',
 ARRAY['Life is long enough if you use it; most hours go to demands, distraction and postponement.','Review the day at night: what went badly, what went well, what was left undone.','Time-use awareness changes behaviour modestly and reliably; the weekly audit is the practical form.'],
 ARRAY['Take the last seven days and sort your waking hours roughly into three blocks: given to others'' demands, lost to distraction, lived deliberately.','Find the one hour you would most like back, and name what took it.','Put that hour in next week''s calendar with a specific use, and protect it like money.'],
 '[{"author": "Note", "title": "Original lesson on the ideas of Seneca; the essays and letters are in the public domain"}, {"author": "Seneca", "title": "De Brevitate Vitae (On the Shortness of Life)", "year": 49}, {"author": "Seneca", "title": "De Ira (On Anger), Book III, on the evening review", "year": 45}, {"author": "Whillans, A. V. et al.", "title": "Buying time promotes happiness (PNAS)", "year": 2017}]'::jsonb,
 '[{"q": "What is Seneca''s answer to \"life is too short\"?", "choices": ["It is, so hurry", "It is long enough; most of it is wasted on demands, distraction and postponement", "Time is an illusion"], "correct": 1, "explain": "The essay''s whole argument is that the shortage is in the use, not the supply."}, {"q": "What does the weekly audit end with?", "choices": ["A feeling of guilt", "One specific hour reclaimed and scheduled", "A new productivity app"], "correct": 1, "explain": "Awareness changes behaviour when it becomes one concrete move."}]'::jsonb,
 323, NULL, 'protocol',
 'seneca',
 'If your last seven days were the shape of your whole life, what would a stranger say you value?',
 'You reclaimed one hour. What did you put in it, and did it feel like living or like another task?',
 15),

-- ─── Aristotle ───
('wisdom', 'aristotle-habituation',
 'Aristotle: Character Is a Habit',
 'Twenty-three centuries before the habit books, the argument that virtue is built by doing, not by knowing',
 'In the Nicomachean Ethics, Aristotle says we become just by doing just acts and brave by doing brave ones, the way builders become builders by building. Character is a settled disposition formed by repetition. The practice is choosing one trait, finding the smallest act it is made of, and repeating it for a week.',
 'strong', 4,
 ARRAY['A clear model of how a trait is built: not by insight, but by repeated acts until they feel like you','The mean: a way to aim a trait between its two failure modes instead of overshooting','The habit-formation research, which supports the mechanism with real numbers'],
 ARRAY['The habit literature supports repetition to automaticity; Aristotle''s wider claims about the good life are philosophy, not findings','The famous line "we are what we repeatedly do" is Will Durant''s 1926 summary, not Aristotle''s sentence; the idea is his, the quote is not','Choosing a trait you do not actually value produces a performance, not a habit'],
 E'Aristotle taught in Athens in the fourth century BC, and the Nicomachean Ethics, named for his son, is the set of lecture notes that survived. Book II makes an argument that the modern habit literature has spent forty years confirming. Virtues are not given to us by nature and they are not learned by hearing about them. They are acquired by doing, the way skills are. You become a builder by building; you become brave by doing brave things while afraid.\n\n**Hexis: the settled state**\nThe word Aristotle uses for a trait is hexis, a having, a settled disposition. A brave person is not someone who feels no fear; it is someone in whom the brave act has become the default response to fear. That default is built by repetition, and it goes both ways: doing the cowardly thing repeatedly builds a coward. The unsettling part of the argument is that there is no neutral. Every day you are habituating something.\n\n**The mean**\nAristotle''s second tool is aim. Every virtue sits between two failure modes: courage between cowardice and recklessness, generosity between meanness and waste, confidence between self-doubt and arrogance. This is not a call to be lukewarm. The mean is relative to the person and the situation, and it is often nearer one extreme than the other. It tells you which way you personally tend to miss, so the practice can lean against it.\n\n**What the research adds**\nLally and colleagues followed people forming a new daily habit and found automaticity rising with repetition along a curve that plateaued after a median of 66 days, with a wide spread. Missing a single day did not break the curve. Later work on habit strength points the same way: repetition in a stable context, not willpower or understanding, is what turns an act into a default. That is Aristotle''s mechanism with a number attached, and it is why the practice below earns a strong chip: it is the habit-formation procedure, aimed by the mean.\n\n**Where it meets your week**\nEvery habit on your check-in is a hexis in the making. This piece asks you to pick one that is a trait rather than a task, patience, courage, honesty, and find the daily act it is made of.',
 'The check-in builds habits. Aristotle points out that some habits are traits, and that you are always building one. Choosing which, and aiming it, is the difference between a routine and a character.',
 ARRAY['Traits are built by repeated acts, not by knowing about them; there is no neutral day.','Aim between the two failure modes of the trait, leaning against the one you tend toward.','Habit research supports the mechanism: repetition in a stable context, missed days forgiven.'],
 ARRAY['Choose one trait you want, and write the two ways it fails: too little and too much.','Find the smallest daily act that trait is made of, something you can do in under two minutes.','Attach it to a fixed moment in your day and repeat it for seven days, counting the days, not the feeling.'],
 '[{"author": "Note", "title": "Original lesson on the ideas of Aristotle; the Nicomachean Ethics is in the public domain"}, {"author": "Aristotle", "title": "Nicomachean Ethics, Book II", "year": -350}, {"author": "Lally, P. et al.", "title": "How are habits formed: Modelling habit formation in the real world (Eur. J. Soc. Psychol.)", "year": 2010}, {"author": "Durant, W.", "title": "The Story of Philosophy (source of the misattributed \"we are what we repeatedly do\")", "year": 1926}]'::jsonb,
